Action.Str:
// TaskerMCP.Dispatch, step 1 (JavaScriptlet).
//
// Authenticates the request, parses the JSON body, and either answers it
// directly (sets status/body/ctype and route = "respond") or sets `route` plus
// arg_* locals for the Tasker actions that follow in the task. Lower-case
// variables declared here with `var` flow back into the task as %name.
//
// Tasker exposes the HTTP Request event's locals as plain JS variables:
// http_request_method, http_request_path, http_request_body, and the array
// http_request_headers ("name:value" strings).

var status = "500";
var ctype = "application/json";
var body = "";
var route = "respond";
var arg_task = "";
var arg_par1 = "";
var arg_par2 = "";
var arg_name = "";
var arg_value = "";
var arg_passthrough = "";
var arg_debug = "0";
var arg_t0 = String(Date.now());

function reply(code, obj) {
  status = String(code);
  body = JSON.stringify(obj);
  route = "respond";
}

function readLocal(fn) {
  try {
    var v = fn();
    if (v === undefined || v === null) return "";
    v = String(v);
    // An unset Tasker variable can surface as its own literal name.
    return /^%[a-z_]+$/.test(v) ? "" : v;
  } catch (_e) {
    return "";
  }
}

function headerList() {
  try {
    return http_request_headers || [];
  } catch (_e) {
    return [];
  }
}

function authorized(token) {
  var hs = headerList();
  for (var i = 0; i < hs.length; i++) {
    var m = /^\s*authorization\s*:\s*bearer\s+(\S+)\s*$/i.exec(String(hs[i]));
    if (m && m[1] === token) return true;
  }
  return false;
}

var GLOBAL_NAME = /^[A-Za-z][A-Za-z0-9_]*$/;

function main() {
  var token = readLocal(function () {
    return global("TaskerMCP_Token");
  });
  if (!token) return reply(503, { error: "TaskerMCP_Token is not set: run the TaskerMCP.Setup task" });
  if (!authorized(token)) return reply(401, { error: "unauthorized" });

  var method = readLocal(function () {
    return http_request_method;
  }).toUpperCase();
  var path =
    readLocal(function () {
      return http_request_path;
    }).replace(/\/+$/, "") || "/";
  var raw = readLocal(function () {
    return http_request_body;
  });
  var req = {};
  var isXml = path === "/import" || path === "/config";
  if (raw && !isXml) {
    try {
      req = JSON.parse(raw);
    } catch (e) {
      return reply(400, { error: "body is not valid JSON: " + e.message });
    }
    if (req === null || typeof req !== "object") req = {};
  }

  var key = method + " " + path;
  switch (key) {
    case "GET /ping":
      return reply(200, {
        ok: true,
        project: global("TaskerMCP_Version") || "",
        tasker: global("TaskerMCP_TaskerVersion") || "",
        device: global("DEVMOD") || "",
      });
    case "GET /backup":
      route = "backup";
      return;
    case "GET /list":
      route = "list";
      return;
    case "POST /import":
      if (!raw) return reply(400, { error: "empty body: POST the TaskerData XML of one task" });
      route = "import";
      return;
    case "POST /config":
      if (!raw || raw.indexOf("<TaskerData") < 0)
        return reply(400, { error: "body must be a full TaskerData XML configuration" });
      route = "config";
      return;
    case "POST /run":
      if (!req.task) return reply(400, { error: "missing 'task'" });
      arg_task = String(req.task);
      arg_par1 = req.par1 === undefined ? "" : String(req.par1);
      arg_par2 = req.par2 === undefined ? "" : String(req.par2);
      arg_debug = req.debug ? "1" : "0";
      if (req.variables && typeof req.variables === "object") {
        var names = [];
        for (var k in req.variables) {
          if (!/^[a-z][a-z0-9_]*$/.test(k))
            return reply(400, { error: "variable names must be lower case locals: " + k });
          setLocal(k, String(req.variables[k]));
          names.push(k);
        }
        arg_passthrough = names.join(",");
      }
      if (arg_debug === "1") setGlobal("TaskerMCP_Debug", "[]");
      route = "run";
      return;
    case "POST /stop":
      if (!req.task) return reply(400, { error: "missing 'task'" });
      arg_task = String(req.task);
      route = "stop";
      return;
    case "POST /vars/get":
      if (!GLOBAL_NAME.test(String(req.name || "")))
        return reply(400, { error: "invalid variable name" });
      var v = global(String(req.name));
      var isSet = v !== undefined && v !== null && String(v) !== "" && String(v) !== "%" + req.name;
      return reply(200, isSet ? { name: req.name, value: String(v), set: true } : { name: req.name, set: false });
    case "POST /vars/set":
      if (!GLOBAL_NAME.test(String(req.name || "")) || !/[A-Z]/.test(String(req.name)))
        return reply(400, { error: "global variable names need at least one upper case letter" });
      setGlobal(String(req.name), req.value === undefined ? "" : String(req.value));
      return reply(200, { ok: true });
    case "POST /vars/list":
      route = "varlist";
      return;
    case "POST /profile":
      if (!req.name) return reply(400, { error: "missing 'name'" });
      var done = enableProfile(String(req.name), Boolean(req.enabled));
      return done
        ? reply(200, { ok: true })
        : reply(404, { error: "no profile named " + req.name });
    case "POST /command":
      if (!req.command) return reply(400, { error: "missing 'command'" });
      arg_value = String(req.command);
      route = "command";
      return;
    case "POST /token/rotate":
      route = "rotate";
      return;
    case "GET /runlog":
      route = "runlog";
      return;
    default:
      return reply(404, { error: "no route " + key });
  }
}

try {
  main();
} catch (e) {
  reply(500, { error: "dispatch failed: " + e.message });
}

// TaskerMCP.Dispatch, last JavaScriptlet before the HTTP Response.
//
// Builds the response body for routes that ran Tasker actions after the
// dispatcher (backup, list, import, run, ...). Routes the dispatcher answered
// itself arrive here with route = "respond" and are left alone.
//
// Errors from actions that run with "Continue Task After Error" surface as the
// locals %err / %errmsg.
//
// Locals set by an earlier JavaScriptlet are NOT visible here as plain JS
// variables (observed on Tasker 6.6.20), so every input is read with local()
// and the outputs are declared with var so Tasker copies them back.

var route = String(local("route") || "");
var status = String(local("status") || "500");
var ctype = String(local("ctype") || "application/json");
var body = String(local("body") || "");

function readLocal(fn) {
  try {
    var v = typeof fn === "string" ? local(fn) : fn();
    if (v === undefined || v === null) return "";
    v = String(v);
    return /^%[a-z_0-9]+$/.test(v) ? "" : v;
  } catch (_e) {
    return "";
  }
}

function list(name) {
  var v;
  try {
    // Local Tasker arrays are injected as JS arrays (this worked for the
    // Test Tasker results); fall back to local("x") and then x1..xN.
    try {
      v = eval(name);
    } catch (_e) {
      v = local(name);
    }
    if (v !== undefined && v !== null && typeof v === "object" && v.length !== undefined) {
      var arr = [];
      for (var j = 0; j < v.length; j++) arr.push(String(v[j]));
      return arr;
    }
    if (v === undefined || v === null || v === "" || /^%[a-z_0-9]+$/.test(String(v))) {
      var items = [];
      for (var i = 1; i < 100000; i++) {
        var item = local(name + i);
        if (item === undefined || item === null || item === "" || /^%/.test(String(item))) break;
        items.push(String(item));
      }
      return items;
    }
  } catch (_e) {
    return [];
  }
  if (v === undefined || v === null) return [];
  if (typeof v === "string") {
    if (/^%[a-z_0-9]+$/.test(v) || v === "") return [];
    return v.split(",");
  }
  var out = [];
  for (var i = 0; i < v.length; i++) out.push(String(v[i]));
  return out;
}

function respond(code, obj) {
  status = String(code);
  body = typeof obj === "string" ? obj : JSON.stringify(obj);
  route = "respond";
}

function failed() {
  return readLocal("err") !== "";
}

function failure() {
  return (
    readLocal("errmsg") || "action failed (err " + readLocal("err") + ")"
  );
}

function finish() {
  switch (route) {
    case "backup":
      if (failed()) return respond(500, { error: "Data Backup failed: " + failure() });
      var xml = readFile("/sdcard/Tasker/tasker-mcp/backup.xml");
      if (!xml) return respond(500, { error: "backup file was empty" });
      ctype = "text/xml";
      return respond(200, xml);
    case "list":
      return respond(200, {
        projects: list("mcp_projects"),
        profiles: list("mcp_profiles"),
        tasks: list("mcp_tasks"),
        scenes: list("mcp_scenes"),
        globals: list("mcp_globals"),
      });
    case "varlist":
      return respond(200, {
        globals: list("mcp_globals"),
      });
    case "import":
      if (failed()) return respond(500, { error: "Import Data failed: " + failure() });
      return respond(200, { ok: true });
    case "run": {
      var known = list("mcp_tasks");
      var wanted = String(local("arg_task"));
      if (known.length && known.indexOf(wanted) < 0)
        return respond(200, {
          ok: false,
          durationMs: 0,
          error: "no task named " + wanted + "; use list_tasks",
        });
      var out = { ok: !failed(), durationMs: Date.now() - Number(local("arg_t0")) };
      var ret = readLocal("mcp_result");
      if (ret !== "") out["return"] = ret;
      if (failed()) out.error = failure();
      if (local("arg_debug") === "1") {
        try {
          out.debug = JSON.parse(global("TaskerMCP_Debug") || "[]");
        } catch (_e) {
          out.debug = [];
        }
      }
      return respond(200, out);
    }
    case "stop":
    case "command":
      if (failed()) return respond(500, { error: failure() });
      return respond(200, { ok: true });
    case "rotate": {
      var t = global("TaskerMCP_Token");
      if (!t) return respond(500, { error: "token rotation failed" });
      return respond(200, { token: t });
    }
    case "runlog": {
      // Tasker has no action that exports the Run Log, and readFile() on a
      // missing file aborts the script, so this route only reports that.
      return respond(501, {
        error: "Tasker has no Run Log export action; use get_logcat (Debug To System Log) instead",
      });
    }
    default:
      return undefined;
  }
}

try {
  finish();
} catch (e) {
  respond(500, { error: "finish failed: " + e.message });
}

// TaskerMCP.Setup, after two Tasker Function GenerateUUID() calls that leave
// their results in %mcp_uuid1 and %mcp_uuid2 (UUID.randomUUID, SecureRandom).
//
// Builds a 64 hex character bearer token, stores it in %TaskerMCP_Token, and
// writes it to a file adb can pull on an emulator. Any failure lands in
// %TaskerMCP_SetupError so it is visible in the Tasker VARS tab.

var mcp_setup_error = "";
try {
  var mcp_new = (String(local("mcp_uuid1")) + String(local("mcp_uuid2")))
    .replace(/-/g, "")
    .toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(mcp_new)) throw new Error("bad uuid output: " + mcp_new);
  setGlobal("TaskerMCP_Token", mcp_new);
  setGlobal("TaskerMCP_Version", "1");
  writeFile("/sdcard/Download/tasker-mcp-token.txt", mcp_new, false);
  setGlobal("TaskerMCP_SetupError", "");
} catch (e) {
  mcp_setup_error = String(e && e.message ? e.message : e);
  setGlobal("TaskerMCP_SetupError", mcp_setup_error);
}

// TaskerMCP.Debug: Perform Task this with %par1 = a message to add it to the
// debug channel that run_task returns when called with debug: true.

var items;
try {
  items = JSON.parse(global("TaskerMCP_Debug") || "[]");
} catch (_e) {
  items = [];
}
if (!Array.isArray(items)) items = [];
items.push(String(local("par1")));
if (items.length > 500) items = items.slice(items.length - 500);
setGlobal("TaskerMCP_Debug", JSON.stringify(items));
